import random

def get_word():
    """Generate a random word from a list of words."""
    words = [
        "python",
        "javascript",
        "kotlin",
        "ruby",
        "javascript",
        # Add more words here
    ]
    return random.choice(words).lower()

def play_hangman():
    """Play a game of Hangman with the user."""
    word = get_word()
    num_guesses = 6
    guessed_letters = set()

    while num_guesses > 0:
        print(f"You have {num_guesses} guesses left.")

        user_guess = input("Enter a letter: ").lower()

        if len(user_guess) != 1:
            print("Please enter a single letter.")
            continue

        if user_guess in guessed_letters:
            print("You've already guessed that letter.")
            continue

        guessed_letters.add(user_guess)

        for i, char in enumerate(word):
            if char == user_guess:
                print(f"You got {char} right! {''.join([char if index == i else '_' for index, letter in enumerate(word)])}")
            elif char in guessed_letters:
                print(f"You've already guessed {char}.")
            else:
                print(f"That letter is not in the word.")

        if '_' not in ''.join([char for char in word if char != user_guess]):
            print(f"Congratulations! You guessed the word: {word}.")
            break

        num_guesses -= 1

    else:
        print(f"Sorry, you ran out of guesses. The word was {word}.")

if __name__ == "__main__":
    play_hangman()
```

This program generates a random word from a list of words, and then plays the game with the user. The user is given 6 guesses to guess the word, and the game displays the number of remaining guesses and the partially guessed word at each turn.
